"use client";

// pendulum-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import { Caption, Foot, Screen } from "./chrome";

/* -------------------------------- pendulum -------------------------------- */

export function PendulumDemo() {
  const reduce = useReducedMotion();
  const target = useMotionValue(0);
  const tilt = useSpring(target, { stiffness: 70, damping: 11 });
  const r1 = useTransform(tilt, (v) => v * 0.78);
  const r2 = useTransform(tilt, (v) => v * 1.12);
  const r3 = useTransform(tilt, (v) => v * 0.92);

  const digits = [
    { d: "4", left: "31%", len: 58, rotate: r1 },
    { d: "0", left: "50%", len: 82, rotate: r2 },
    { d: "4", left: "69%", len: 66, rotate: r3 },
  ];

  function move(e: React.PointerEvent<HTMLDivElement>) {
    if (reduce) return;
    const r = e.currentTarget.getBoundingClientRect();
    target.set(((e.clientX - r.left) / r.width - 0.5) * 26);
  }

  return (
    <Screen
      onPointerMove={move}
      onPointerLeave={() => target.set(0)}
      className="bg-[#07080a]"
    >
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_50%_40%,rgba(242,237,227,0.055),transparent_66%)]" />

      <div className="absolute inset-x-[12%] top-[18%] h-px bg-white/25" />
      {digits.map((p) => (
        <span
          key={p.left}
          className="absolute top-[17.4%] size-[5px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-fg/70"
          style={{ left: p.left }}
        />
      ))}

      {digits.map((p) => (
        <motion.div
          key={p.left}
          className="absolute top-[18%] origin-top"
          style={{ left: p.left, rotate: p.rotate }}
        >
          <div
            className="absolute left-0 top-0 w-px -translate-x-1/2 bg-[linear-gradient(180deg,rgba(242,237,227,0.55),rgba(242,237,227,0.18))]"
            style={{ height: p.len }}
          />
          <div
            className="absolute left-0 -translate-x-1/2"
            style={{ top: p.len - 4 }}
          >
            <span className="display block text-[52px] leading-none text-fg drop-shadow-[0_3px_10px_rgba(8,9,10,0.5)]">
              {p.d}
            </span>
          </div>
        </motion.div>
      ))}

      <div className="pointer-events-none absolute bottom-[19%] left-1/2 h-px w-[46%] -translate-x-1/2 bg-[repeating-linear-gradient(to_right,rgba(242,237,227,0.22)_0_3px,transparent_3px_8px)]" />

      <div className="pointer-events-none absolute inset-x-0 bottom-[46px] text-center lab-mono text-[9px] text-white/45">
        push the number off balance
      </div>

      <Caption label="404 / pendulum" />
      <Foot method="pendulum · pointer" />
    </Screen>
  );
}

"use client";

import Image from "next/image";
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ArrowUpRight, Check, Copy } from "lucide-react";

export const EASE = [0.22, 1, 0.36, 1] as const;

/* Every card shares the same framing so the grid reads as one set. */

export function Caption({
  label,
  className = "",
}: {
  label: string;
  className?: string;
}) {
  return (
    <span
      className={`pointer-events-none absolute left-4 top-3 z-20 lab-mono text-[10px] tracking-[0.02em] text-white/75 [text-shadow:0_1px_3px_rgba(8,9,10,0.6)] ${className}`}
    >
      {label}
    </span>
  );
}

export function HomeLink({ label = "back home" }: { label?: string }) {
  return (
    <span className="pointer-events-none inline-flex items-center gap-1 lab-mono text-[10px] text-white/70">
      {label}
      <ArrowUpRight className="size-3" strokeWidth={1.5} />
    </span>
  );
}

export function Foot({
  method,
  label,
}: {
  method: string;
  label?: string;
}) {
  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 flex items-center justify-between px-4 pb-3">
      <HomeLink label={label} />
      <span className="lab-mono text-[10px] text-white/50">{method}</span>
    </div>
  );
}

const SCREEN =
  "group @container relative h-full w-full overflow-hidden bg-ink-900";

export function Screen({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"div">) {
  return (
    <div {...rest} className={`${SCREEN} ${className}`}>
      {children}
    </div>
  );
}

export function ScreenButton({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"button">) {
  return (
    <button
      type="button"
      {...rest}
      className={`${SCREEN} cursor-default text-left ${className}`}
    >
      {children}
    </button>
  );
}

export function Plate({
  src,
  className = "",
  sizes = "(max-width: 768px) 100vw, 33vw",
  opacity,
  position = "center",
}: {
  src: string;
  className?: string;
  sizes?: string;
  opacity?: number;
  position?: string;
}) {
  return (
    <Image
      src={src}
      alt=""
      fill
      sizes={sizes}
      className={`object-cover ${className}`}
      style={{ opacity, objectPosition: position }}
    />
  );
}

/* --------------------------------- helpers -------------------------------- */

export function useReplay() {
  const [run, setRun] = useState(0);
  return { run, replay: () => setRun((n) => n + 1) };
}

export function useStill() {
  return useReducedMotion() ?? false;
}

export const clamp = (v: number, min: number, max: number) =>
  Math.max(min, Math.min(max, v));

/* ------------------------------- install bits ------------------------------ */

export function CopyCommand({
  command,
  className = "",
}: {
  command: string;
  className?: string;
}) {
  const [done, setDone] = useState(false);

  async function copy() {
    try {
      await navigator.clipboard.writeText(command);
      setDone(true);
      setTimeout(() => setDone(false), 1600);
    } catch {
      setDone(false);
    }
  }

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={`Copy ${command}`}
      className={`group/copy flex w-full items-center justify-between gap-4 rounded-control border border-line bg-ink-900 px-3 py-2.5 text-left transition-colors duration-200 hover:border-line-2 active:translate-y-px ${className}`}
    >
      <code className="min-w-0 break-all lab-mono text-[10px] text-fg-2 sm:truncate lg:text-[12px]">
        <span className="mr-1.5 text-amber/80">$</span>
        {command}
      </code>
      <span className="shrink-0 text-fg-3 transition-colors duration-200 group-hover/copy:text-fg">
        {done ? (
          <Check className="size-4" strokeWidth={1.5} />
        ) : (
          <Copy className="size-4" strokeWidth={1.5} />
        )}
      </span>
    </button>
  );
}

export function Reveal({
  children,
  delay = 0,
  className = "",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduce ? false : { opacity: 0, y: 10 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-60px" }}
      transition={{ duration: 0.55, ease: EASE, delay }}
    >
      {children}
    </motion.div>
  );
}
